INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('d3077932-428b-1fac-4457-19db1da4a458', 'VERAL Electric 5 metrli o''lchov tasmasi (Ruletka)', 'veral-electric-5m-ruletka', 'VERAL Electric — professional o''lchov ishlari uchun yuqori sifatli 5 metrli ruletka. Lentasining qalinligi 19mm, aniq va yorqin shkalaga ega. Ergonomik kauchuk korpusi sirpanib ketishdan va zarbadan himoya qiladi. Avtomatik qulflanish funksiyasi ishlashni osonlashtiradi.', 20000, 30000, 33, 'b244b549-7683-0d68-276c-ec76105164a1', 'VERAL electric', 50, 'VRL-5M-19', 5, 12, '/products/veral_5m.jpg', true, false, true, '{"O''lchov uzunligi":"5 metr","Tasma kengligi":"19 mm","Material":"ABS plastik + Kauchuk","Korpus xususiyati":"Zarbaga chidamli","Avto-qulflash":"Mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('04187f9b-d08e-b25e-5b83-d7bbbfe34f8d', 'BIYOTI BYT-2602 Perforator (Rotary Hammer)', 'biyoti-byt-2602-perforator', 'BIYOTI BYT-2602 — uy va yarim professional qurilish ishlari uchun mo''ljallangan kuchli perforator (otboynik). U 3 ta rejimda ishlaydi: burg''ulash, zarbli burg''ulash va o''yish. Komplektda mustahkam plastik keys, qo''shimcha tutqich, chuqurlik o''lchagich, 3 ta SDS-plus pichoq va 2 ta iskana (zubilo) mavjud. Yuqori sifatli Yevropa standarti asosida ishlab chiqarilgan.', 460000, 520000, 11, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'BIYOTI', 25, 'BYT-2602', 4.8, 15, '/products/biyoti_byt2602.png', true, false, true, '{"Ish rejimlari":"3 ta rejim (Teshish, Zarbali teshish, O''yish)","Patron turi":"SDS-Plus","Komplektatsiya":"Keys, 3 ta sverlo, 2 ta zubilo","Standart":"Made for EURO","Quvvat turi":"Tarmoqli (220V)"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('3b16d551-5c26-0d6c-e2c5-196850d64cd2', 'ADEGSO 10289 Kantselyariya/Oboy pichog''i', 'adegso-oboy-pichogi-10289', 'ADEGSO (Model: 10289) — qog''oz, karton, oboy va boshqa materiallarni kesish uchun mo''ljallangan yuqori sifatli ''ustalar tanlovi'' pichog''i. Pichoqning uchini sindirib, doimiy o''tkir holatda ishlatish mumkin (Snap-off blade). Korpusi qulay ushlash uchun maxsus teksturali dizaynga ega.', 10000, 15000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 100, 'ADG-10289', 4.9, 8, '/products/adegso_knife_10289.png', true, false, true, '{"Pichoq turi":"Sindirib yangilanadigan (Snap-off)","Vazifasi":"Oboy, qog''oz, karton kesish","Korpus materiali":"Qattiq plastmassa + rezina qo''shimchalar","Model":"10289"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('78f84cc9-2fff-33ac-9577-c6f9f7072fbb', 'ADEGSO 10287 Buklanadigan Oboy pichog''i (Raskladnoy)', 'adegso-oboy-pichogi-buklanadigan-10287', 'ADEGSO (Model: 10287) — ixcham va qulay, buklanadigan (raskladnoy) oboy pichog''i. Pichoq uchi trapez shaklida bo''lib, o''ta o''tkir kesish xususiyatiga ega. Komplektda qo''shimcha zaxira lezviyalar saqlanadigan kichik kassetasi ham bor. ''Ustalar tanlovi'' toifasiga kiruvchi yuqori sifatli asbob.', 30000, 40000, 25, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 75, 'ADG-10287', 5, 12, '/products/adegso_knife_10287.png', true, false, true, '{"Pichoq turi":"Buklanadigan (Raskladnoy / Yig''iluvchi)","Vazifasi":"Oboy, qog''oz, gipsokarton, linoleum kesish","Komplektatsiya":"Pichoq + Zaxira pichoqchalar (lezviya)","Model":"10287"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('e9b54450-9185-2fc3-caaf-fc28bb5e0fa5', 'RUR R1817 Indikatorli Otvyortka (Tok tekshirgich)', 'rur-r1817-indikatorli-otvyortka', 'RUR (Model: R1817) — elektr toki bor-yo''qligini xavfsiz va aniq tekshirish uchun mo''ljallangan indikatorli otvyortka. Uch qismi yuqori sifatli qotishmadan qilingan bo''lib, oddiy otvyortka sifatida ham ishlatish mumkin. Chirog''i yorqin yonadi va tutqichi qulay plastikdan ishlangan.', 12000, 18000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 120, 'RUR-R1817', 4.8, 22, '/products/rur_r1817.png', true, false, true, '{"Turi":"Indikatorli (Tester)","Vazifasi":"Elektr toki mavjudligini tekshirish","Model":"R1817","Material":"Izolyatsiyalangan plastmassa va po''lat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('58408080-d50f-2d32-7746-c29edd9a4b6c', 'RUR R3039 Krokodil (Ploskogubsi / Klyuch)', 'rur-r3039-krokodil-ploskogubsi', 'RUR (Model: R3039) — santexnika va mexanika ishlari uchun mo''ljallangan universal sozlanuvchi qisqich (krokodil / gazoviy klyuch). Turli o''lchamdagi truba va gaykalarni mahkam siqish uchun ko''p pog''onali sozlash mexanizmiga ega. Yuqori mustahkamlikdagi po''latdan ishlangan, tutqichi sirpanmaydigan qoplamali.', 95000, 120000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 60, 'RUR-R3039', 5, 18, '/products/rur_r3039.png', true, false, true, '{"Turi":"Sozlanuvchi qisqich (Krokodil)","Model":"R3039","Material":"Yuqori sifatli karbonli po''lat","Tutqich":"Sirpanmaydigan, ergonomik qoplama","Qo''llanilishi":"Santexnika, mexanika, ta''mirlash"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('2ceeac26-9e1f-9bc2-5645-9230fcc1199e', 'EAFIXS Bog'' qaychisi (Sekator / Pruning shears)', 'eafixs-bog-qaychisi-sekator', 'EAFIXS Professional Tools — daraxt shoxlari, uzum toklarini va gul butalarini kesish uchun mo''ljallangan yuqori sifatli sekator. Qalinligi 20mm gacha bo''lgan shoxlarni osonlik bilan qirqadi. SKS+ sifatli po''latdan ishlangan, tutqichi ergonomik va sirpanmaydi. Sifat kafolati (Industrial / TUV GS).', 55000, 70000, 21, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'EAFIXS', 80, 'EAF-SEKATOR', 4.9, 14, '/products/eafixs_sekator.png', true, false, true, '{"Kesish diametri":"20 mm gacha","Pichoq materiali":"SKS+ Yuqori sifatli po''lat","Vazifasi":"Bog''dorchilik, shoxlarni kesish","Sifat standarti":"TUV GS / Industrial","Tutqich":"Sirpanmaydigan qoplama, qulflanuvchi"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('92a63c05-3e39-5b42-5470-a50d68303244', 'RUR R1816 Elektron Indikatorli Otvyortka (Raqamli Displey)', 'rur-r1816-elektron-indikator', 'RUR (Model: R1816) — tok kuchlanishini (12-250V) raqamli displeyda aniq ko''rsatuvchi elektron indikator-otvyortka. Dark Vision funksiyasi tufayli qorong''i joylarda ham ko''rsatkichlarni bemalol o''qish mumkin. Elektriklar va uy ustalari uchun juda qulay va zamonaviy asbob.', 40000, 55000, 27, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'RUR', 90, 'RUR-R1816', 4.9, 17, '/products/rur_r1816.png', true, false, true, '{"Turi":"Elektron indikator (Tester)","Kuchlanish diapazoni":"AC/DC 12V-250V","Displey":"Raqamli LCD (Dark Vision)","Vazifasi":"Tokni va kuchlanishni tekshirish","Model":"R1816"}'::jsonb) ON CONFLICT (id) DO NOTHING;
